"""
Media helpers shared by every module.

* Storage names are ALWAYS generated by the server: `<prefix>/<uuid hex>.<detected ext>`.
  The client file name is only kept (sanitised) for display, so there is no path traversal and
  no overwrite of another user's file.
* Public media (announcement covers) use the default storage (MEDIA_ROOT / object storage).
* Private media (achievement evidence) use `STORAGES["private"]`, which lives OUTSIDE
  MEDIA_ROOT and has no base URL: it can only be read through an authenticated endpoint.
* Files are deleted only after the surrounding transaction commits, so a rollback never leaves a
  database row pointing at a deleted file.
"""
import logging
import os
import re
import unicodedata
import uuid
from io import BytesIO

from django.core.files.base import ContentFile
from django.core.files.storage import storages
from django.db import transaction
from PIL import Image, ImageOps

from .validators import IMAGE_FORMATS

logger = logging.getLogger("common")

_UNSAFE_CHARS = re.compile(r"[^A-Za-z0-9._ -]+")
_MULTI = re.compile(r"[ ._-]{2,}")
_SAFE_SEGMENT = re.compile(r"^[A-Za-z0-9_-]+$")


def private_storage():
    """Callable used as `FileField(storage=private_storage)` (resolved lazily)."""
    return storages["private"]


def safe_display_name(filename, *, default="file", max_length=100):
    """
    Sanitised name for DISPLAY only (e.g. "Certificate (final).pdf" -> "Certificate final.pdf").
    Never used to build a storage path.
    """
    name = (filename or "").replace("\\", "/").rsplit("/", 1)[-1]
    name = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode("ascii")
    stem, ext = os.path.splitext(name)
    ext = re.sub(r"[^A-Za-z0-9]", "", ext)[:10]
    stem = _UNSAFE_CHARS.sub(" ", stem)
    stem = _MULTI.sub(lambda m: m.group(0)[0], stem).strip(" .-_")
    if not stem:
        stem = default
    ext = f".{ext.lower()}" if ext else ""
    if len(stem) + len(ext) > max_length:
        stem = stem[: max_length - len(ext)].rstrip(" .-_") or default
    return stem + ext


def build_storage_name(*segments, extension):
    """
    "announcements/covers/<uuid>/<random>.jpg". Every segment must be a plain identifier
    (UUIDs, fixed words), so ".." or "/" can never reach the storage layer.

    Use it inside a module-level `upload_to(instance, filename)` function (Django migrations
    must be able to import upload_to callables, so closures/factories are not used).
    """
    parts = []
    for segment in segments:
        segment = str(segment)
        if not _SAFE_SEGMENT.match(segment):
            raise ValueError(f"Unsafe path segment: {segment!r}")
        parts.append(segment)
    extension = extension.lower().lstrip(".")
    if not _SAFE_SEGMENT.match(extension):
        raise ValueError("Unsafe extension")
    parts.append(f"{uuid.uuid4().hex}.{extension}")
    return "/".join(parts)


def reencode_image(upload, image_format, *, max_edge=2048):
    """
    Re-encode an image that already passed validation: strips EXIF/GPS and any appended payload,
    applies camera rotation, caps the longest side and proves the full file decodes.
    Returns (ContentFile, width, height, extension).
    """
    upload.seek(0)
    with Image.open(upload) as source:
        source.load()
        image = ImageOps.exif_transpose(source)
    image.thumbnail((max_edge, max_edge), Image.Resampling.LANCZOS)
    buffer = BytesIO()
    if image_format == "JPEG":
        if image.mode not in ("RGB", "L"):
            image = image.convert("RGB")
        image.save(buffer, "JPEG", quality=85, optimize=True)
    elif image_format == "PNG":
        if image.mode not in ("RGB", "RGBA", "L", "LA", "P"):
            image = image.convert("RGBA")
        image.save(buffer, "PNG", optimize=True)
    else:
        image.save(buffer, "WEBP", quality=85)
    extension = IMAGE_FORMATS[image_format][0]
    width, height = image.size
    return ContentFile(buffer.getvalue(), name=f"image.{extension}"), width, height, extension


def delete_stored_file(storage, name):
    """Delete a stored file; never raises (cleanup must not break a request)."""
    if not name:
        return
    try:
        storage.delete(name)
    except Exception:
        logger.warning("Could not delete stored file %s", name)


def delete_file_on_commit(field_file):
    """Delete the file behind a FieldFile once the current transaction commits."""
    if not field_file or not field_file.name:
        return
    storage, name = field_file.storage, field_file.name
    transaction.on_commit(lambda: delete_stored_file(storage, name))


def list_stored_files(storage, prefix):
    """Recursively list file names below `prefix` (FileSystemStorage / S3-compatible listdir)."""
    found = []
    try:
        directories, files = storage.listdir(prefix)
    except (FileNotFoundError, NotImplementedError, OSError):
        return found
    found.extend(f"{prefix}/{f}" for f in files)
    for directory in directories:
        found.extend(list_stored_files(storage, f"{prefix}/{directory}"))
    return found
